        f_pvalue = None

    return {
        "ok": True,
        "engine": "pyodide",
        "functionalForm": form,
        "yName": y_label,
        "xNames": x_labels,
        "seType": se_type,
        "nobs": int(results.nobs),
        "coefficients": coefficients,
        "rSquared": r_squared,
        "rSquaredAdj": finite_or_none(results.rsquared_adj),
        "fStat": f_stat,
        "fPValue": f_pvalue,
        "dfResid": int(results.df_resid),
        "residualStdError": residual_std_error,
        "residuals": residuals,
        "fitted": fitted,
        "warnings": warnings,
        "rlsTest": rls_test,
        "breuschPagan": breusch_pagan,
    }


